1	import { useRef, useState, useEffect, useMemo } from 'react';
2	import { useNavigate, useParams } from 'react-router-dom';
3	import { useFights } from '../hooks/useFights';
4	import { useEvents } from '../hooks/useEvents';
5	import { useFighterFrames } from '../hooks/useFighterFrames';
6	import { useRounds } from '../hooks/useRounds';
7	import { useWindowWidth } from '../hooks/useWindowWidth';
8	import {
9	  createEvent, updateEvent, deleteEvent, finishLabeling, deleteFight, reopenLabeling,
10	  type CreateEventPayload,
11	} from '../services/api';
12	import type { SpanKind } from '../components/annotate/taxonomy';
13	import { isEditingLabels, isFightViewable, isLabelEditable, isLabelingReady, needsRoundReview, STATE_LABELS } from '../types/Fight';
14	import type { Event } from '../types/Event';
15	import { describeEvent } from '../utils/describeEvent';
16	import { isFrameSwapped } from '../utils/cornerSwap';
17	import ConfirmDialog from '../components/ConfirmDialog';
18	import VideoControls from '../components/VideoControls';
19	import FrameInfo from '../components/FrameInfo';
20	import type { FighterOverlayHandle } from '../components/FighterOverlay';
21	import AnnotateStage from '../components/annotate/AnnotateStage';
22	import FighterSelectCard from '../components/annotate/FighterSelectCard';
23	import EventPalette from '../components/annotate/EventPalette';
24	import FightEndModal, { type FightEndResult } from '../components/annotate/FightEndModal';
25	import KeyboardLegend from '../components/annotate/KeyboardLegend';
26	import AnnotationPanel from '../components/annotate/AnnotationPanel';
27	import SaveStatus from '../components/annotate/SaveStatus';
28	import FightPurposeBadge from '../components/FightPurposeBadge';
29	import { KEYMAP, colorForAction, iconForAction, successForAction, type Corner, type ToolItem } from '../components/annotate/taxonomy';
30	
31	export default function Annotate() {
32	  const { id } = useParams<{ id: string }>();
33	  const navigate = useNavigate();
34	  const fightId = id ? Number(id) : null;
35	
36	  const videoRef = useRef<HTMLVideoElement>(null);
37	  const overlayRef = useRef<FighterOverlayHandle>(null);
38	  const rafRef = useRef<number | null>(null);
39	  const fpsRef = useRef<number>(30);
40	  const lastFrameRef = useRef<number>(-1);
41	  const [isPlaying, setIsPlaying] = useState(false);
42	  const [currentTime, setCurrentTime] = useState(0);
43	  const [duration, setDuration] = useState(0);
44	
45	  const { fights, setFights } = useFights();
46	  const selectedFight = fights.find(f => f.id === fightId) ?? null;
47	  const { events: allEvents, setEvents: setAllEvents } = useEvents(fightId, { source: 'label' });
48	  const events = useMemo(() => allEvents.filter(e => e.kind === 'point'), [allEvents]);
49	  const spans = useMemo(() => allEvents.filter(e => e.kind !== 'point'), [allEvents]);
50	  const { frameMap } = useFighterFrames(fightId);
51	  const { rounds } = useRounds(fightId);
52	  const width = useWindowWidth();
53	  const narrow = width < 1100;
54	
55	  const fps = selectedFight?.fps ?? 30;
56	  fpsRef.current = fps;
57	
58	  const ready = selectedFight !== null && isLabelingReady(selectedFight.state);
59	
60	  useEffect(() => {
61	    const video = videoRef.current;
62	    if (!video || !ready) return;
63	    if (!isPlaying) {
64	      if (rafRef.current !== null) {
65	        video.cancelVideoFrameCallback(rafRef.current);
66	        rafRef.current = null;
67	      }
68	      return;
69	    }
70	    const tick = (_now: DOMHighResTimeStamp, metadata: VideoFrameCallbackMetadata) => {
71	      const frame = Math.floor(metadata.mediaTime * fpsRef.current) + 1;
72	      overlayRef.current?.draw(frame);
73	      if (frame !== lastFrameRef.current) {
74	        lastFrameRef.current = frame;
75	        setCurrentTime(metadata.mediaTime);
76	      }
77	      rafRef.current = video.requestVideoFrameCallback(tick);
78	    };
79	    rafRef.current = video.requestVideoFrameCallback(tick);
80	    return () => {
81	      if (rafRef.current !== null) {
82	        video.cancelVideoFrameCallback(rafRef.current);
83	        rafRef.current = null;
84	      }
85	    };
86	  }, [isPlaying, ready]);
87	
88	  const currentFrame = Math.floor(currentTime * fps) + 1;
89	  const currentMs = Math.floor(currentTime * 1000);
90	  const videoSrc = selectedFight ? `/fights/${selectedFight.id}/video` : undefined;
91	
92	  const togglePlay = () => {
93	    const video = videoRef.current;
94	    if (!video) return;
95	    if (isPlaying) video.pause(); else video.play();
96	    setIsPlaying(!isPlaying);
97	  };
98	
99	  const stepFrame = (delta: number) => {
100	    const video = videoRef.current;
101	    if (!video) return;
102	    video.pause();
103	    setIsPlaying(false);
104	    const newTime = Math.min(Math.max(video.currentTime + delta / fps, 0), video.duration);
105	    video.currentTime = newTime;
106	    setCurrentTime(newTime);
107	    overlayRef.current?.draw(Math.floor(newTime * fpsRef.current) + 1);
108	  };
109	
110	  const handleSeek = (time: number) => {
111	    const video = videoRef.current;
112	    if (!video) return;
113	    video.currentTime = time;
114	    setCurrentTime(time);
115	    overlayRef.current?.draw(Math.floor(time * fpsRef.current) + 1);
116	  };
117	
118	  const seekToFrame = (frame: number) => handleSeek(Math.max(0, (frame - 1) / fps));
119	
120	  const currentRound = rounds.find(r => currentFrame >= r.start_frame && currentFrame <= r.end_frame)?.round_number ?? '-';
121	
122	  const redName = selectedFight?.red_fighter_name ?? 'Red corner';
123	  const blueName = selectedFight?.blue_fighter_name ?? 'Blue corner';
124	
125	  // Reconstructs each point event's display text on the fly (description is
126	  // only ever stored for fight_end) — including the swap-corrected fighter
127	  // name for any event whose own frame falls inside a corner_swap span, so
128	  // reviewing the timeline reflects a swap the moment it's marked, even for
129	  // strikes logged before the span existed.
130	  const cornerSwapSpans = useMemo(
131	    () => spans.filter(s => s.kind === 'corner_swap').map(s => ({ frame: s.frame, end_frame: s.end_frame })),
132	    [spans],
133	  );
134	  const describe = (e: Event) => describeEvent(e, {
135	    redName, blueName, swapped: isFrameSwapped(e.frame, cornerSwapSpans),
136	  });
137	
138	  // ---- annotation logging state ----
139	  const [selected, setSelected] = useState<Corner | null>(null);
140	  const [toast, setToast] = useState<{ text: string; color: string; icon: string } | null>(null);
141	  const [flashId, setFlashId] = useState<number | null>(null);
142	  const [hint, setHint] = useState(false);
143	  const [endOpen, setEndOpen] = useState(false);
144	  const [savingCount, setSavingCount] = useState(0);
145	  const [finishing, setFinishing] = useState(false);
146	  const [reopening, setReopening] = useState(false);
147	  const [reopenError, setReopenError] = useState<string | null>(null);
148	  const [confirmDelete, setConfirmDelete] = useState(false);
149	  const [deletingFight, setDeletingFight] = useState(false);
150	  const [deleteError, setDeleteError] = useState<string | null>(null);
151	  // Timeline clip selected by click — Delete removes it. Separate from
152	  // `flashId` (a transient highlight after creation) and from `selected`
153	  // (the red/blue corner for the *next* logged event).
154	  const [selectedEventId, setSelectedEventId] = useState<number | null>(null);
155	
156	  const frameRef = useRef(1);
157	  frameRef.current = currentFrame;
158	  const selRef = useRef<Corner | null>(null);
159	  selRef.current = selected;
160	  const endOpenRef = useRef(false);
161	  endOpenRef.current = endOpen;
162	  const confirmDeleteRef = useRef(false);
163	  confirmDeleteRef.current = confirmDelete;
164	  const selectedEventIdRef = useRef<number | null>(null);
165	  selectedEventIdRef.current = selectedEventId;
166	  const sessionIdsRef = useRef<number[]>([]);
167	
168	  const toastTimer = useRef<ReturnType<typeof setTimeout>>(undefined);
169	  const hintTimer = useRef<ReturnType<typeof setTimeout>>(undefined);
170	  const flashTimer = useRef<ReturnType<typeof setTimeout>>(undefined);
171	
172	  const showToast = (text: string, color: string, icon: string) => {
173	    setToast({ text, color, icon });
174	    clearTimeout(toastTimer.current);
175	    toastTimer.current = setTimeout(() => setToast(null), 1100);
176	  };
177	
178	  const flash = (eventId: number) => {
179	    setFlashId(eventId);
180	    clearTimeout(flashTimer.current);
181	    flashTimer.current = setTimeout(() => setFlashId(null), 700);
182	  };
183	
184	  const addEvent = async (payload: CreateEventPayload) => {
185	    if (!fightId) return null;
186	    setSavingCount(c => c + 1);
187	    try {
188	      const created = await createEvent(fightId, { kind: 'point', ...payload });
189	      setAllEvents(prev => [...prev, created]);
190	      sessionIdsRef.current.push(created.id);
191	      flash(created.id);
192	      return created;
193	    } catch {
194	      showToast('Failed to save event', 'var(--f-red)', 'error');
195	      return null;
196	    } finally {
197	      setSavingCount(c => c - 1);
198	    }
199	  };
200	
201	  const removeEvent = async (eventId: number) => {
202	    if (!fightId) return;
203	    setSavingCount(c => c + 1);
204	    try {
205	      await deleteEvent(fightId, eventId);
206	      setAllEvents(prev => prev.filter(e => e.id !== eventId));
207	      sessionIdsRef.current = sessionIdsRef.current.filter(x => x !== eventId);
208	      if (selectedEventIdRef.current === eventId) setSelectedEventId(null);
209	    } catch {
210	      showToast('Failed to delete event', 'var(--f-red)', 'error');
211	    } finally {
212	      setSavingCount(c => c - 1);
213	    }
214	  };
215	
216	  // corner_swap / excluded are start/end toggles: one key opens a span at the
217	  // playhead, the next press of the same key closes it. `openSpanRef` tracks
218	  // the in-flight span id per kind so the second press knows what to close.
219	  const openSpanRef = useRef<Partial<Record<SpanKind, number>>>({});
220	  const SPAN_LABEL: Record<SpanKind, string> = { round: 'Round', corner_swap: 'Corner swap', excluded: 'Excluded' };
221	
222	  // openSpanRef only lives in memory — leaving Annotate and coming back (or a
223	  // reload) resets it to {} even though an unclosed span from the previous
224	  // session is still sitting in the loaded data with end_frame=null. Reseed
225	  // it once that data arrives, or the next O/P press opens a second span
226	  // instead of closing the first.
227	  useEffect(() => {
228	    for (const kind of ['corner_swap', 'excluded'] as const) {
229	      if (openSpanRef.current[kind] != null) continue;
230	      const open = spans.find(s => s.kind === kind && s.end_frame == null);
231	      if (open) openSpanRef.current[kind] = open.id;
232	    }
233	  }, [spans]);
234	
235	  const toggleSpan = async (kind: SpanKind) => {
236	    if (!fightId) return;
237	    const openId = openSpanRef.current[kind];
238	    const frame = frameRef.current;
239	    if (openId != null) {
240	      try {
241	        const start = spans.find(s => s.id === openId)?.frame ?? frame;
242	        const patch = frame < start ? { frame, end_frame: start } : { end_frame: frame };
243	        const updated = await updateEvent(fightId, openId, patch);
244	        setAllEvents(prev => prev.map(s => (s.id === openId ? updated : s)));
245	        showToast(`${SPAN_LABEL[kind]} span closed`, 'var(--slate-400)', 'flag');
246	      } catch {
247	        showToast('Failed to close span', 'var(--f-red)', 'error');
248	      } finally {
249	        delete openSpanRef.current[kind];
250	      }
251	      return;
252	    }
253	    try {
254	      const created = await createEvent(fightId, {
255	        kind, frame, value: kind === 'excluded' ? 'replay' : null,
256	      });
257	      setAllEvents(prev => [...prev, created]);
258	      openSpanRef.current[kind] = created.id;
259	      showToast(`${SPAN_LABEL[kind]} span opened`, 'var(--slate-400)', 'flag');
260	    } catch {
261	      showToast('Failed to open span', 'var(--f-red)', 'error');
262	    }
263	  };
264	
265	  const updateSpan = async (spanId: number, patch: { frame?: number; end_frame?: number }) => {
266	    if (!fightId) return;
267	    try {
268	      const updated = await updateEvent(fightId, spanId, patch);
269	      setAllEvents(prev => prev.map(s => (s.id === spanId ? updated : s)));
270	    } catch {
271	      showToast('Failed to update span', 'var(--f-red)', 'error');
272	    }
273	  };
274	
275	  const removeSpan = async (spanId: number) => {
276	    if (!fightId) return;
277	    try {
278	      await deleteEvent(fightId, spanId);
279	      setAllEvents(prev => prev.filter(s => s.id !== spanId));
280	      for (const [kind, id] of Object.entries(openSpanRef.current)) {
281	        if (id === spanId) delete openSpanRef.current[kind as SpanKind];
282	      }
283	    } catch {
284	      showToast('Failed to delete span', 'var(--f-red)', 'error');
285	    }
286	  };
287	
288	  const undo = () => {
289	    const lastId = sessionIdsRef.current[sessionIdsRef.current.length - 1];
290	    if (lastId == null) return;
291	    removeEvent(lastId);
292	  };
293	
294	  const logTool = (item: ToolItem, shiftKey = false) => {
295	    if (!selectedFight) return;
296	    const corner = selRef.current;
297	    if (item.needsFighter && !corner) {
298	      setHint(true);
299	      clearTimeout(hintTimer.current);
300	      hintTimer.current = setTimeout(() => setHint(false), 1100);
301	      showToast('Select a fighter first', 'var(--f-red)', 'error');
302	      return;
303	    }
304	    // Fighter-independent tools (fight state) must not pick up whichever corner
305	    // happens to be selected — neither in the stored corner nor in the toast.
306	    const cornerIdx = item.needsFighter ? (corner === 'red' ? 0 : 1) : null;
307	    const fighterName = item.needsFighter ? (corner === 'red' ? redName : blueName) : '';
308	    const target = item.hasTarget ? (shiftKey ? 'body' : 'head') : item.fixedTarget ?? null;
309	    // `description` is only kept as a local for the toast text below — it's
310	    // no longer sent to the backend. Every action here except fight_end is
311	    // fully reconstructable from action/target/corner (see describeEvent.ts),
312	    // so storing a frozen copy would only go stale the next time a
313	    // corner_swap span is added or edited.
314	    const description = item.text(fighterName, target ?? undefined);
315	    const color = colorForAction(item.action);
316	    const icon = iconForAction(item.action);
317	    addEvent({
318	      frame: frameRef.current,
319	      corner: cornerIdx,
320	      action: item.action,
321	      target,
322	      success: successForAction(item.action),
323	    }).then(created => {
324	      if (!created) return;
325	      if (!item.needsFighter) { showToast(description, color, icon); return; }
326	      const targetSuffix = item.hasTarget ? ` · ${target === 'body' ? 'Body' : 'Head'}` : '';
327	      showToast(`${item.name} · ${fighterName}${targetSuffix}`, color, icon);
328	    });
329	  };
330	
331	  const confirmFightEnd = (result: FightEndResult) => {
332	    const winnerCorner = result.winner === 'red' ? 0 : result.winner === 'blue' ? 1 : null;
333	    const winnerName = result.winner === 'red' ? redName : result.winner === 'blue' ? blueName : null;
334	    const outcome = result.method === 'Draw' || !winnerName
335	      ? 'Draw'
336	      : result.method === 'Decision' ? `${winnerName} by decision` : `${winnerName} by ${result.method}`;
337	    const description = `Fight ended — ${outcome}${result.detail ? ' (' + result.detail + ')' : ''}`;
338	    const endFrame = frameRef.current;
339	    addEvent({
340	      frame: endFrame,
341	      description,
342	      corner: winnerCorner,
343	      action: 'fight_end',
344	      success: null,
345	    }).then(created => {
346	      if (!created) return;
347	      showToast(`Fight ended · ${result.method}`, 'var(--purple-600)', 'sports_score');
348	
349	      // The round span was seeded from the AI's scheduled-length guess,
350	      // which now runs past the real end of the fight — auto-exclude the
351	      // tail so it isn't scored/trained on as if it were live action.
352	      // Visible and editable in the timeline like any other excluded span,
353	      // not a silent adjustment (TODO.md #4).
354	      if (!fightId) return;
355	      const containingRound = spans.find(
356	        s => s.kind === 'round' && s.frame <= endFrame &&
357	             (s.end_frame == null || endFrame <= s.end_frame),
358	      );
359	      if (containingRound?.end_frame != null && containingRound.end_frame > endFrame) {
360	        createEvent(fightId, {
361	          kind: 'excluded',
362	          frame: endFrame + 1,
363	          end_frame: containingRound.end_frame,
364	          value: 'post fight_end',
365	        }).then(span => setAllEvents(prev => [...prev, span]));
366	      }
367	    });
368	    setEndOpen(false);
369	  };
370	
371	  const handleFinishLabeling = async () => {
372	    if (!fightId) return;
373	    setFinishing(true);
374	    try {
375	      await finishLabeling(fightId);
376	      // replace: Back from the Player must not land on this page again, which
377	      // for a now-finished fight is just the "already labeled" screen.
378	      navigate(`/fights/${fightId}`, { replace: true });
379	    } catch (err) {
380	      showToast(err instanceof Error ? err.message : 'Failed to finish labeling', 'var(--f-red)', 'error');
381	      setFinishing(false);
382	    }
383	  };
384	
385	  // Same transition the Player's "Edit labels" button makes, for a direct
386	  // visit to /annotate on a finished fight. Patching the one row in place
387	  // flips `ready`, so this page re-renders straight into the editor.
388	  const handleReopenLabeling = async () => {
389	    if (!fightId) return;
390	    setReopening(true);
391	    setReopenError(null);
392	    try {
393	      const reopened = await reopenLabeling(fightId);
394	      setFights(prev => prev.map(f => (f.id === reopened.id ? reopened : f)));
395	    } catch (err) {
396	      setReopenError(err instanceof Error ? err.message : 'Failed to open the fight for editing');
397	    } finally {
398	      setReopening(false);
399	    }
400	  };
401	
402	  const handleDeleteFight = async () => {
403	    if (!fightId) return;
404	    setDeletingFight(true);
405	    setDeleteError(null);
406	    try {
407	      // The DELETE unlinks the file this <video> is streaming — stop playback
408	      // (and the requestVideoFrameCallback loop) before pulling it out from under us.
409	      videoRef.current?.pause();
410	      setIsPlaying(false);
411	      await deleteFight(fightId);
412	      // replace: Back must not return to a now-dead /fights/{id}/annotate.
413	      navigate('/', { replace: true });
414	    } catch (err) {
415	      setDeleteError(err instanceof Error ? err.message : 'Failed to delete fight');
416	      setDeletingFight(false);
417	    }
418	  };
419	
420	  // stable "latest callback" ref so the global keydown listener (registered once)
421	  // always calls the current render's closures, without re-registering constantly
422	  const fnsRef = useRef({ togglePlay, stepFrame, logTool, undo, setSelected, toggleSpan, removeEvent });
423	  fnsRef.current = { togglePlay, stepFrame, logTool, undo, setSelected, toggleSpan, removeEvent };
424	
425	  useEffect(() => {
426	    if (!ready) return;
427	    const onKey = (e: KeyboardEvent) => {
428	      if (e.metaKey || e.ctrlKey || e.altKey) return;
429	      const target = e.target as HTMLElement;
430	      const tag = target.tagName;
431	      if (tag === 'INPUT' || tag === 'TEXTAREA' || target.isContentEditable) return;
432	      // Any modal swallows every shortcut — otherwise z/o/p/digits keep logging
433	      // label events behind the overlay, and Escape would double-fire.
434	      if (endOpenRef.current || confirmDeleteRef.current) return;
435	
436	      const fns = fnsRef.current;
437	      const k = e.key;
438	      const time = (frameRef.current - 1) / fpsRef.current;
439	
440	      if (k === ' ') { e.preventDefault(); fns.togglePlay(); return; }
441	      if (k === 'ArrowLeft') { e.preventDefault(); handleSeek(Math.max(0, time - (e.shiftKey ? 5 : 1))); return; }
442	      if (k === 'ArrowRight') { e.preventDefault(); handleSeek(time + (e.shiftKey ? 5 : 1)); return; }
443	      if (k === ',') { e.preventDefault(); fns.stepFrame(-1); return; }
444	      if (k === '.') { e.preventDefault(); fns.stepFrame(1); return; }
445	      if (k === 'Escape') { fns.setSelected(null); setSelectedEventId(null); return; }
446	
447	      const lk = k.length === 1 ? k.toLowerCase() : k;
448	      if (lk === 'r') { fns.setSelected('red'); return; }
449	      if (lk === 'b') { fns.setSelected('blue'); return; }
450	      // Backspace/Delete: delete the selected timeline clip if one is
451	      // selected, else undo the last event logged this session. On Mac the
452	      // one physical "delete" key sends Backspace (e.key === 'Delete' is
453	      // only the separate forward-delete, Fn+Delete) — so this has to be
454	      // one binding that branches on selection, not two separate keys.
455	      if (k === 'Backspace' || k === 'Delete') {
456	        e.preventDefault();
457	        if (selectedEventIdRef.current != null) fns.removeEvent(selectedEventIdRef.current);
458	        else fns.undo();
459	        return;
460	      }
461	      if (lk === 'z') { e.preventDefault(); fns.undo(); return; }
462	      if (lk === 'o') { e.preventDefault(); fns.toggleSpan('corner_swap'); return; }
463	      if (lk === 'p') { e.preventDefault(); fns.toggleSpan('excluded'); return; }
464	
465	      // Digit keys need e.code, not e.key: Shift+1 types '!' on a US layout,
466	      // so reading e.key would break the KEYMAP lookup for the target modifier.
467	      const toolKey = e.code.startsWith('Digit') ? e.code.slice(5) : lk;
468	      const tool = KEYMAP[toolKey];
469	      if (tool) { e.preventDefault(); fns.logTool(tool, e.shiftKey); }
470	    };
471	    window.addEventListener('keydown', onKey);
472	    return () => window.removeEventListener('keydown', onKey);
473	  }, [ready]);
474	
475	  // ---- guard states ----
476	  if (selectedFight === null) {
477	    return (
478	      <div style={{ display: 'flex', flex: 1, alignItems: 'center', justifyContent: 'center', minHeight: 'calc(100vh - 58px)', padding: 24 }}>
479	        <span className="material-symbols-outlined" style={{ fontSize: 32, color: '#64748b', animation: 'spin 1.5s linear infinite' }}>progress_activity</span>
480	      </div>
481	    );
482	  }
483	
484	  if (isFightViewable(selectedFight.state)) {
485	    return (
486	      <div style={{ display: 'flex', flex: 1, alignItems: 'center', justifyContent: 'center', minHeight: 'calc(100vh - 58px)', padding: 24 }}>
487	        <div style={{
488	          textAlign: 'center', background: 'rgba(255,255,255,0.04)', backdropFilter: 'blur(24px) saturate(160%)',
489	          border: '1px solid rgba(255,255,255,0.07)', borderRadius: 20, padding: '48px 56px', maxWidth: 420,
490	        }}>
491	          <span className="material-symbols-outlined" style={{ fontSize: 40, color: 'var(--accent)', display: 'block', marginBottom: 16 }}>check_circle</span>
492	          <h2 style={{ fontSize: 20, fontWeight: 800, margin: '0 0 10px', color: '#f1f5f9' }}>This fight is already labeled</h2>
493	          <p style={{ fontSize: 14, color: '#475569', margin: '0 0 20px', lineHeight: 1.6 }}>Open it in the Player to review the tagged events.</p>
