18	  { key: '2', num: '2', cat: 'strike', sub: 'Landed', name: 'Straight right', text: (f) =&gt; `${f} straight right to the head` },
19	  { key: '3', num: '3', cat: 'strike', sub: 'Landed', name: 'Left hook', text: (f) =&gt; `${f} left hook to the head` },
20	  { key: '4', num: '4', cat: 'strike', sub: 'Landed', name: 'Right hook', text: (f) =&gt; `${f} right hook to the body` },
21	  { key: '5', num: '5', cat: 'strike', sub: 'Landed', name: 'Left uppercut', text: (f) =&gt; `${f} left uppercut on the inside` },
22	  { key: '6', num: '6', cat: 'strike', sub: 'Landed', name: 'Right uppercut', text: (f) =&gt; `${f} right uppercut on the inside` },
