24	  { key: 'l', cat: 'strike', sub: 'Landed', name: 'Low kick', text: (f) =&gt; `${f} low kick` },
25	  { key: 'm', cat: 'strike', sub: 'Landed', name: 'Middle kick', text: (f) =&gt; `${f} middle kick to the body` },
26	  { key: 'h', cat: 'strike', sub: 'Landed', name: 'High kick', text: (f) =&gt; `${f} high kick to the head` },
27	  { key: 'e', cat: 'strike', sub: 'Landed', name: 'Elbow', text: (f) =&gt; `${f} elbow` },
28	  { key: 'n', cat: 'strike', sub: 'Landed', name: 'Knee', text: (f) =&gt; `${f} knee in the clinch` }]
29	},
30	{ group: 'Grappling', items: [
31	  { key: 't', cat: 'grapple', sub: 'Attempt', name: 'Takedown attempt', text: (f) =&gt; `${f} shoots for a takedown` },
32	  { key: 'd', cat: 'grapple', sub: 'Defended', name: 'Takedown defended', text: (f) =&gt; `${f} defends the takedown` },
33	  { key: 's', cat: 'event', sub: 'Submission attempt', name: 'Submission', text: (f) =&gt; `${f} threatens a submission` }]
34	},
35	{ group: 'Outcome', items: [
36	  { key: 'x', cat: 'strike', sub: 'KNOCKDOWN', name: 'Knockdown', text: (f) =&gt; `${f} scores a KNOCKDOWN` }]
37	},
38	{ group: 'Fight state', items: [
39	  { key: 'w', cat: 'state', sub: '', name: 'Striking', text: () =&gt; 'Fight state \u2192 STRIKING', nf: true },
40	  { key: 'g', cat: 'state', sub: '', name: 'Grappling', text: () =&gt; 'Fight state \u2192 GRAPPLING', nf: true }]
41	}];
42	
43	const KEYMAP = {};
44	TOOL_GROUPS.forEach((g) =&gt; g.items.forEach((it) =&gt; {KEYMAP[it.key] = it;}));
45	
46	/* ---- round / fight timing markers (no fighter, special handling) ---- */
47	const ROUND_TOOLS = [
48	{ kind: 'start', name: 'Round start', icon: 'play_circle', color: 'var(--green-500)' },
49	{ kind: 'end', name: 'Round end', icon: 'stop_circle', color: 'var(--green-500)' },
50	{ kind: 'fightend', name: 'End of fight', icon: 'sports_score', color: 'var(--purple-600)' }];
51	
52	const PLAYBACK_KEYS = [
53	{ k: ['Space'], label: 'Play / pause' },
54	{ k: ['\u2190', '\u2192'], label: 'Seek \u00b11 s' },
55	{ k: ['\u21e7', '\u2190/\u2192'], label: 'Seek \u00b15 s' },
56	{ k: [',', '.'], label: 'Step \u00b11 frame' }];
57	
58	const EDIT_KEYS = [
59	{ k: ['R'], label: 'Select red corner' },
60	{ k: ['B'], label: 'Select blue corner' },
61	{ k: ['Esc'], label: 'Deselect fighter' },
62	{ k: ['Z'], label: 'Undo last event' }];
63	
64	
65	/* ---- clickable fighter boxes over the still ---- */
66	const BOXES = [
67	{ key: 'red', x: 18.5, y: 13, w: 21, h: 71, side: 'left' },
68	{ key: 'blue', x: 53.5, y: 11, w: 21.5, h: 69, side: 'right' }];
69	
70	function FighterBoxes({ selected, onSelect }) {
71	  return (
72	    &lt;&gt;
73	      {BOXES.map((b) =&gt; {
74	        const f = AF.fighters[b.key];const sel = selected === b.key;
75	        return (
76	          &lt;button key={b.key} className="fbox" onClick={(e) =&gt; {e.stopPropagation();onSelect(b.key);}}
77	          style={{ position: 'absolute', left: b.x + '%', top: b.y + '%', width: b.w + '%', height: b.h + '%', cursor: 'pointer',
78	            borderRadius: 6, padding: 0, transition: 'transform .1s',
79	            border: sel ? `2.5px solid ${f.color}` : '2px dashed rgba(255,255,255,0.45)',
80	            background: sel ? `color-mix(in srgb, ${f.color} 15%, transparent)` : 'transparent',
81	            boxShadow: sel ? `0 0 0 3px color-mix(in srgb, ${f.color} 32%, transparent)` : 'none' }}&gt;
82	            &lt;span style={{ position: 'absolute', top: -27, [b.side]: 0, display: 'flex', alignItems: 'center', gap: 6, whiteSpace: 'nowrap',
83	              background: sel ? f.color : 'rgba(0,0,0,0.62)', color: sel ? '#0a0a0a' : '#fff',
84	              fontSize: 11, fontWeight: 800, padding: '3px 8px', borderRadius: 5, backdropFilter: 'blur(6px)', letterSpacing: '0.02em' }}&gt;
