const isFightEnd = (e) =&gt; e.cat === 'event' &amp;&amp; /^Fight ended/.test(e.text);

/* track geometry */
const TL = { ruler: 26, round: 30, state: 30, lane: 46, head: 132 };

function useMeasure() {
  const ref = useRef(null);
  const [w, setW] = useState(0);
  useEffect(() =&gt; {
    if (!ref.current) return;
    const ro = new ResizeObserver((es) =&gt; {for (const e of es) setW(e.contentRect.width);});
    ro.observe(ref.current);
    return () =&gt; ro.disconnect();
  }, []);
  return [ref, w];
}

/* ---- one event clip on a fighter lane ---- */
function Clip({ e, x, color, flash, onSeek, onHover, onDelete }) {
  return (
    &lt;button className="tl-clip" onPointerDown={(ev) =&gt; ev.stopPropagation()}
    onClick={(ev) =&gt; {ev.stopPropagation();onSeek(e.t);}}
    onMouseEnter={(ev) =&gt; onHover({ e, x: ev.currentTarget.offsetLeft, color })}
    onMouseLeave={() =&gt; onHover(null)}
    style={{ position: 'absolute', left: x - 11, top: (TL.lane - 30) / 2, width: 22, height: 30, borderRadius: 7,
      display: 'grid', placeItems: 'center', cursor: 'pointer', zIndex: flash ? 6 : 4,
      border: `1px solid color-mix(in srgb, ${color} ${flash ? 90 : 55}%, transparent)`,
      background: `color-mix(in srgb, ${color} ${flash ? 34 : 18}%, var(--surface-inner))`,
      boxShadow: flash ? `0 0 0 1.5px ${color}, 0 0 16px -2px ${color}` : 'none',
      animation: 'feed-in .25s ease-out' }}&gt;
      &lt;span className="mi" style={{ fontSize: 16, color }}&gt;{window.eventIcon(e)}&lt;/span&gt;
    &lt;/button&gt;);

}

/* ---- the timeline ---- */
function TimelineView({ items, player, onDelete, flashId, filter }) {
  const { time, seek } = player;
  const [zoom, setZoom] = useState(1);
  const [hover, setHover] = useState(null);
  const [scrollRef, scrollW] = useMeasure();
  const draggingRef = useRef(false);

  const fitPx = scrollW &gt; 0 ? scrollW / AF.duration : 2.2;
  const pxPerSec = fitPx * zoom;
  const W = AF.duration * pxPerSec;
  const xFor = (t) =&gt; t * pxPerSec;
  const lanesTop = TL.ruler + TL.round + TL.state;
  const totalH = lanesTop + TL.lane * 2;
  const boxH = totalH + 14; // room for the horizontal scrollbar below the last lane

  /* partition events */
  const fil = (e) =&gt; window.matchFilter(e, filter);
  const redEv = items.filter((e) =&gt; e.fighter === 'red' &amp;&amp; !isFightEnd(e) &amp;&amp; fil(e));
  const blueEv = items.filter((e) =&gt; e.fighter === 'blue' &amp;&amp; !isFightEnd(e) &amp;&amp; fil(e));
  const roundEv = items.filter((e) =&gt; e.cat === 'round' || isFightEnd(e)); // structural — always shown
  const stateEv = useMemo(() =&gt; items.filter((e) =&gt; e.cat === 'state').sort((a, b) =&gt; a.t - b.t), [items]);
  const segs = stateEv.map((e, i) =&gt; ({
    id: e.id, t0: e.t, t1: i + 1 &lt; stateEv.length ? stateEv[i + 1].t : AF.duration,
    grapple: /GRAPPLING/.test(e.text) }));

  /* ruler ticks */
  const targets = [5, 10, 15, 30, 60, 120, 180];
  const tickEvery = targets.find((s) =&gt; s * pxPerSec &gt;= 64) || 240;
  const ticks = [];for (let t = 0; t &lt;= AF.duration; t += tickEvery) ticks.push(t);

  /* scrub */
  const scrubRef = useRef();
  scrubRef.current = (clientX) =&gt; {
    const el = scrollRef.current;if (!el) return;
    const r = el.getBoundingClientRect();
    seek((clientX - r.left + el.scrollLeft) / pxPerSec);
  };
  useEffect(() =&gt; {
    const move = (e) =&gt; {if (draggingRef.current) scrubRef.current(e.clientX);};
    const up = () =&gt; {draggingRef.current = false;};
    window.addEventListener('pointermove', move);window.addEventListener('pointerup', up);
    return () =&gt; {window.removeEventListener('pointermove', move);window.removeEventListener('pointerup', up);};
  }, []);
  const startScrub = (e) =&gt; {draggingRef.current = true;player.setPlaying(false);scrubRef.current(e.clientX);};

  /* keep playhead in view while playing */
  useEffect(() =&gt; {
    const el = scrollRef.current;if (!el) return;
    const x = xFor(time);const L = el.scrollLeft;const R = L + el.clientWidth;
    if (x &lt; L + 48 || x &gt; R - 48) el.scrollLeft = x - el.clientWidth / 2;
  }, [time, pxPerSec]);

  const TrackHead = ({ h, children, top }) =&gt;
