        &lt;button className="icon-btn" title="Fit" onClick={() =&gt; setZoom(1)} style={{ width: 28, height: 28, color: zoom === 1 ? 'var(--accent)' : 'var(--text-secondary)' }}&gt;&lt;span className="mi" style={{ fontSize: 16 }}&gt;fit_screen&lt;/span&gt;&lt;/button&gt;
        &lt;button className="icon-btn" title="Zoom in" onClick={() =&gt; setZoom((z) =&gt; Math.min(12, +(z + 0.5).toFixed(1)))} style={{ width: 28, height: 28 }}&gt;&lt;span className="mi" style={{ fontSize: 17 }}&gt;add&lt;/span&gt;&lt;/button&gt;
      &lt;/div&gt;
    &lt;/div&gt;);

}

/* ---- list view rows (original feed, reused) ---- */
function FeedRows({ shown, seek, onDelete, flashId }) {
  const scrollRef = useRef();
  useEffect(() =&gt; {if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;}, [shown.length]);
  return (
    &lt;div ref={scrollRef} style={{ maxHeight: 256, overflowY: 'auto', padding: '4px 2px', display: 'grid', gridTemplateColumns: 'repeat(auto-fill,minmax(320px,1fr))', gap: 9 }}&gt;
      {shown.length === 0 &amp;&amp;
      &lt;div style={{ gridColumn: '1/-1', textAlign: 'center', color: 'var(--text-disabled)', fontSize: 13, padding: '30px 20px' }}&gt;
          &lt;span className="mi" style={{ fontSize: 34, opacity: 0.3, display: 'block', marginBottom: 8 }}&gt;add_box&lt;/span&gt;
          No annotations yet. Tap a fighter, then log an event.&lt;/div&gt;
      }
      {shown.map((e) =&gt; {
        const c = window.eventColor(e);const fr = e.fighter ? AF.fighters[e.fighter] : null;
        return (
          &lt;div key={e.id} className="event-row" onClick={() =&gt; seek(e.t)}
          style={{ display: 'flex', gap: 11, alignItems: 'flex-start', padding: '11px 12px', borderRadius: 11, cursor: 'pointer', position: 'relative',
            border: '1px solid var(--border-subtle)', background: 'var(--surface-inner)', borderLeft: `3px solid ${c}`,
            boxShadow: e.id === flashId ? `0 0 0 1.5px ${c}, 0 0 18px -4px ${c}` : 'none', animation: 'feed-in .3s ease-out' }}&gt;
            &lt;span style={{ width: 28, height: 28, flexShrink: 0, borderRadius: 7, display: 'grid', placeItems: 'center',
              background: `color-mix(in srgb, ${c} 14%, transparent)`, border: `1px solid color-mix(in srgb, ${c} 30%, transparent)` }}&gt;
              &lt;span className="mi" style={{ fontSize: 16, color: c }}&gt;{window.eventIcon(e)}&lt;/span&gt;
            &lt;/span&gt;
            &lt;span style={{ minWidth: 0, flex: 1 }}&gt;
              &lt;span style={{ display: 'flex', alignItems: 'center', gap: 7, marginBottom: 2 }}&gt;
                {fr &amp;&amp; &lt;span style={{ width: 7, height: 7, borderRadius: 2, background: fr.color }}&gt;&lt;/span&gt;}
                &lt;span style={{ fontSize: 13, fontWeight: 600, color: 'var(--text-primary)', lineHeight: 1.25 }}&gt;{e.text}&lt;/span&gt;
              &lt;/span&gt;
              &lt;span style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: 11, color: 'var(--text-disabled)' }}&gt;
                &lt;span style={{ fontVariantNumeric: 'tabular-nums', color: 'var(--text-muted)', fontWeight: 700 }}&gt;{e.tc}&lt;/span&gt;
                {e.sub &amp;&amp; &lt;span style={{ color: c, fontWeight: 600 }}&gt;{e.sub}&lt;/span&gt;}
                &lt;span style={{ marginLeft: 'auto', opacity: 0.7 }}&gt;#{e.frame}&lt;/span&gt;
              &lt;/span&gt;
            &lt;/span&gt;
            &lt;button className="del-btn" title="Delete" onClick={(ev) =&gt; {ev.stopPropagation();onDelete(e.id);}}
            style={{ position: 'absolute', top: 8, right: 8, width: 22, height: 22, borderRadius: 6, border: 'none', cursor: 'pointer',
              background: 'rgba(255,255,255,0.05)', color: 'var(--text-muted)', display: 'grid', placeItems: 'center' }}&gt;
              &lt;span className="mi" style={{ fontSize: 14 }}&gt;close&lt;/span&gt;
            &lt;/button&gt;
          &lt;/div&gt;);

      })}
    &lt;/div&gt;);

}

/* ---- panel: header + view toggle + body ---- */
function AnnotationPanel({ items, player, onDelete, flashId }) {
  const [view, setView] = useState(() =&gt; localStorage.getItem('annot-view') || 'timeline');
  const [filter, setFilter] = useState('all');
  useEffect(() =&gt; {localStorage.setItem('annot-view', view);}, [view]);
  const shown = useMemo(() =&gt; [...items].filter((e) =&gt; window.matchFilter(e, filter)).sort((a, b) =&gt; a.t - b.t), [items, filter]);

  const ViewBtn = ({ id, icon, label }) =&gt;
  &lt;button onClick={() =&gt; setView(id)} className="seg-btn"
  style={{ display: 'inline-flex', alignItems: 'center', gap: 6, padding: '6px 12px', borderRadius: 7, cursor: 'pointer', fontSize: 12, fontWeight: 700,
    border: 'none', background: view === id ? 'var(--accent)' : 'transparent', color: view === id ? 'var(--cyan-on)' : 'var(--text-muted)' }}&gt;
    &lt;span className="mi" style={{ fontSize: 16 }}&gt;{icon}&lt;/span&gt;{label}&lt;/button&gt;;

  return (
    &lt;div className="glass" style={{ borderRadius: 16, padding: '16px 18px 18px', marginTop: 16 }}&gt;
      &lt;div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 14, flexWrap: 'wrap' }}&gt;
        &lt;span style={{ width: 8, height: 8, borderRadius: '50%', background: 'var(--accent)', boxShadow:'none' }}&gt;&lt;/span&gt;
        &lt;span className="disp-title" style={{ fontSize: 21, fontFamily: "'Bebas Neue'", letterSpacing: '0.04em', color: 'var(--text-primary)' }}&gt;ANNOTATION TIMELINE&lt;/span&gt;
        &lt;span style={{ fontSize: 11.5, color: 'var(--text-disabled)', fontWeight: 700 }}&gt;{items.length} events&lt;/span&gt;
        &lt;span style={{ flex: 1 }}&gt;&lt;/span&gt;
        &lt;div style={{ display: 'flex', gap: 6 }}&gt;
          {window.FILTERS.map((f) =&gt;
          &lt;button key={f.key} className={'pill' + (filter === f.key ? ' active' : '')} onClick={() =&gt; setFilter(f.key)}&gt;{f.label}&lt;/button&gt;
          )}
        &lt;/div&gt;
        &lt;div style={{ display: 'flex', gap: 3, padding: 3, borderRadius: 9, background: 'var(--surface-inner)', border: '1px solid var(--border-glass)' }}&gt;
          &lt;ViewBtn id="timeline" icon="view_timeline" label="Timeline" /&gt;
          &lt;ViewBtn id="list" icon="view_list" label="List" /&gt;
        &lt;/div&gt;
      &lt;/div&gt;
      {view === 'timeline' ?
      &lt;TimelineView items={items} player={player} onDelete={onDelete} flashId={flashId} filter={filter} /&gt; :
      &lt;FeedRows shown={shown} seek={player.seek} onDelete={onDelete} flashId={flashId} /&gt;}
    &lt;/div&gt;);

}

/* ---- auto-save status pill ---- */
function SaveStatus({ state }) {
  const saving = state === 'saving';
  return (
    &lt;div style={{ display: 'inline-flex', alignItems: 'center', gap: 7, padding: '7px 13px', borderRadius: 10,
      border: '1px solid var(--border-glass)', background: 'var(--surface-inner)', color: 'var(--text-secondary)', fontSize: 12.5, fontWeight: 700 }}&gt;
      &lt;span className={'mi' + (saving ? ' spin' : '')} style={{ fontSize: 17, color: saving ? 'var(--text-muted)' : 'var(--green-500)' }}&gt;
        {saving ? 'sync' : 'cloud_done'}&lt;/span&gt;
      {saving ? 'Saving…' : 'All changes saved'}
    &lt;/div&gt;);

}

/* ---- seed a few "previously annotated" events ---- */
function seedAnnotations() {
  const mk = (id, t, cat, fighter, text, sub) =&gt; ({ id, t, frame: Math.round(t * AF.fps), cat, fighter, text, sub: sub || '', tc: AF.fmt(t) });
  return [
  mk(0, 2, 'round', null, 'Round 1 started', ''),
  mk(1, 12, 'strike', 'red', 'BATUR jab to the head', 'Landed'),
  mk(2, 24, 'strike', 'blue', 'STAMATOVIC low kick to the lead leg', 'Landed'),
  mk(3, 96, 'grapple', 'blue', 'STAMATOVIC shoots for a takedown', 'Attempt'),
  mk(4, 99, 'state', null, 'Fight state \u2192 GRAPPLING', ''),
  mk(5, 151, 'strike', 'blue', 'STAMATOVIC elbow from top', 'Landed')];

}

/* ---- screen ---- */
function App() {
  const player = window.usePlayer(AF.duration, 1); // ~real-time
  const [selected, setSelected] = useState(null);
  const [items, setItems] = useState(seedAnnotations);
  const [toast, setToast] = useState(null);
  const [flashId, setFlashId] = useState(null);
  const [hint, setHint] = useState(false);
  const [endOpen, setEndOpen] = useState(false);
  const [saveState, setSaveState] = useState('saved');

  // start paused for frame-accurate work
  useEffect(() =&gt; {player.setPlaying(false);}, []);

  // auto-save: react to any change in the annotation set
  const firstSave = useRef(true);
  useEffect(() =&gt; {
    if (firstSave.current) {firstSave.current = false;return;}
    setSaveState('saving');
    const id = setTimeout(() =&gt; setSaveState('saved'), 650);
    return () =&gt; clearTimeout(id);
  }, [items]);

  // live mirrors for the global key handler
  const timeRef = useRef(0);timeRef.current = player.time;
  const selRef = useRef(null);selRef.current = selected;
  const endRef = useRef(false);endRef.current = endOpen;
  const idRef = useRef(1000);
  const toastTimer = useRef();const hintTimer = useRef();const flashTimer = useRef();

  const showToast = useCallback((text, color, icon) =&gt; {
    setToast({ text, color, icon });
    clearTimeout(toastTimer.current);
    toastTimer.current = setTimeout(() =&gt; setToast(null), 1100);
  }, []);

  const flash = useCallback((id) =&gt; {
    setFlashId(id);clearTimeout(flashTimer.current);flashTimer.current = setTimeout(() =&gt; setFlashId(null), 700);
  }, []);

  const logTool = useCallback((it) =&gt; {
    const f = selRef.current;
    if (!it.nf &amp;&amp; !f) {
      setHint(true);clearTimeout(hintTimer.current);hintTimer.current = setTimeout(() =&gt; setHint(false), 1100);
      showToast('Select a fighter first', 'var(--f-red)', 'error');
      return;
    }
    const t = timeRef.current;
    const fr = !it.nf &amp;&amp; f ? AF.fighters[f] : null;
    const id = ++idRef.current;
    const ev = { id, t: Math.round(t * 100) / 100, frame: Math.round(t * AF.fps), cat: it.cat,
      fighter: it.nf ? null : f, text: it.nf ? it.text() : it.text(fr.name), sub: it.sub, tc: AF.fmt(t) };
    setItems((prev) =&gt; [...prev, ev]);
    showToast(`${it.name}${fr ? ' · ' + fr.name : ''}`, window.eventColor(ev), window.eventIcon(ev));
    flash(id);
  }, [showToast, flash]);

  const logRound = useCallback((kind) =&gt; {
    if (kind === 'fightend') {setEndOpen(true);return;}
    const t = timeRef.current;
    const rd = window.activeRound(t);
    const id = ++idRef.current;
    const text = kind === 'start' ? `Round ${rd} started` : `Round ${rd} ended`;
    const ev = { id, t: Math.round(t * 100) / 100, frame: Math.round(t * AF.fps), cat: 'round', fighter: null, text, sub: '', tc: AF.fmt(t) };
    setItems((prev) =&gt; [...prev, ev]);
    showToast(text, 'var(--green-500)', kind === 'start' ? 'play_circle' : 'stop_circle');
    flash(id);
  }, [showToast, flash]);

  const confirmFightEnd = useCallback(({ method, winner, detail }) =&gt; {
    const t = timeRef.current;
    const rd = window.activeRound(t);
    const wf = winner !== 'none' ? AF.fighters[winner] : null;
    const result = method === 'Draw' || !wf ?
      'Draw' :
      method === 'Decision' ? `${wf.name} by decision` : `${wf.name} by ${method}`;
    const text = `Fight ended \u2014 ${result}${detail ? ' (' + detail + ')' : ''}`;
    const id = ++idRef.current;
    const ev = { id, t: Math.round(t * 100) / 100, frame: Math.round(t * AF.fps), cat: 'event',
      fighter: wf ? winner : null, text, sub: `${method} · R${rd}`, tc: AF.fmt(t) };
    setItems((prev) =&gt; [...prev, ev]);
    showToast(`Fight ended · ${method}`, 'var(--purple-600)', 'sports_score');
    flash(id);
    setEndOpen(false);
  }, [showToast, flash]);

  const undo = useCallback(() =&gt; {
    setItems((prev) =&gt; {
      const mine = prev.filter((a) =&gt; a.id &gt; 1000);
      if (!mine.length) return prev;
      const maxId = Math.max(...mine.map((a) =&gt; a.id));
      return prev.filter((a) =&gt; a.id !== maxId);
    });
  }, []);
  const del = useCallback((id) =&gt; setItems((prev) =&gt; prev.filter((a) =&gt; a.id !== id)), []);

  // stable global keyboard handler via ref
  const fns = useRef({});
  fns.current = { player, logTool, undo, setSelected };
  useEffect(() =&gt; {
    const onKey = (e) =&gt; {
      if (e.metaKey || e.ctrlKey || e.altKey) return;
      const tag = e.target.tagName;
      if (tag === 'INPUT' || tag === 'TEXTAREA' || e.target.isContentEditable) return;
      if (endRef.current) return; // modal captures input
      const p = fns.current.player;const t = timeRef.current;
      const k = e.key;
      if (k === ' ') {e.preventDefault();p.toggle();return;}
      if (k === 'ArrowLeft') {e.preventDefault();p.seek(t - (e.shiftKey ? 5 : 1));return;}
      if (k === 'ArrowRight') {e.preventDefault();p.seek(t + (e.shiftKey ? 5 : 1));return;}
      if (k === ',') {e.preventDefault();p.setPlaying(false);p.seek(t - 1 / AF.fps);return;}
      if (k === '.') {e.preventDefault();p.setPlaying(false);p.seek(t + 1 / AF.fps);return;}
      if (k === 'Escape') {fns.current.setSelected(null);return;}
      const lk = k.length === 1 ? k.toLowerCase() : k;
      if (lk === 'r') {fns.current.setSelected('red');return;}
      if (lk === 'b') {fns.current.setSelected('blue');return;}
      if (k === 'Backspace' || lk === 'z') {e.preventDefault();fns.current.undo();return;}
      const tool = KEYMAP[lk];
      if (tool) {e.preventDefault();fns.current.logTool(tool);}
    };
    window.addEventListener('keydown', onKey);
    return () =&gt; window.removeEventListener('keydown', onKey);
  }, []);

  return (
    &lt;&gt;
      &lt;window.Header active="Annotate" /&gt;
      &lt;div className="annot-page"&gt;
        &lt;div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 16 }}&gt;
