1	import { useEffect, useState } from 'react';
2	import { TOOL_GROUPS, colorForAction, iconForAction, type ToolItem } from './taxonomy';
3	
4	interface EventPaletteProps {
5	  selected: boolean;
6	  onLog: (item: ToolItem, shiftKey?: boolean) => void;
7	  onFightEnd: () => void;
8	}
9	
10	export default function EventPalette({ selected, onLog, onFightEnd }: EventPaletteProps) {
11	  // Live target preview while Shift is held — logTool() already resolves the
12	  // correct target from e.shiftKey at log time, this is purely so the
13	  // button/tooltip shows what's about to be logged before the key is pressed
14	  // (TODO.md #5).
15	  const [shiftHeld, setShiftHeld] = useState(false);
16	  useEffect(() => {
17	    const onKeyDown = (e: KeyboardEvent) => { if (e.key === 'Shift') setShiftHeld(true); };
18	    const onKeyUp = (e: KeyboardEvent) => { if (e.key === 'Shift') setShiftHeld(false); };
19	    const onBlur = () => setShiftHeld(false); // e.g. alt-tab away while holding Shift
20	    window.addEventListener('keydown', onKeyDown);
21	    window.addEventListener('keyup', onKeyUp);
22	    window.addEventListener('blur', onBlur);
23	    return () => {
24	      window.removeEventListener('keydown', onKeyDown);
25	      window.removeEventListener('keyup', onKeyUp);
26	      window.removeEventListener('blur', onBlur);
27	    };
28	  }, []);
29	
30	  return (
31	    <div style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
32	      {TOOL_GROUPS.map(g => (
33	        <div key={g.group}>
34	          <div style={{ display: 'flex', alignItems: 'baseline', gap: 8, marginBottom: 9 }}>
35	            <div className="label" style={{ fontSize: 9.5 }}>{g.group}</div>
36	            {g.note && <div style={{ fontSize: 10, color: 'var(--text-disabled)', fontWeight: 600 }}>{g.note}</div>}
37	          </div>
38	          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2,1fr)', gap: 8 }}>
39	            {g.items.map(it => {
40	              const c = colorForAction(it.action);
41	              const blocked = it.needsFighter && !selected;
42	              const previewTarget = it.hasTarget ? (shiftHeld ? 'Body' : 'Head') : null;
43	              return (
44	                <button
45	                  key={it.key}
46	                  onClick={e => { e.currentTarget.blur(); onLog(it, e.shiftKey); }}
47	                  title={blocked ? 'Select a fighter first' : previewTarget ? `${it.name} · ${previewTarget} (Shift = body)` : it.name}
48	                  style={{
49	                    display: 'flex', alignItems: 'center', gap: 9, padding: '9px 11px', borderRadius: 10,
50	                    cursor: 'pointer', textAlign: 'left', border: '1px solid var(--border-subtle)',
51	                    background: 'var(--surface-inner)', borderLeft: `3px solid ${c}`,
52	                    opacity: blocked ? 0.42 : 1, transition: 'transform .1s,opacity .12s',
53	                    fontFamily: 'inherit',
54	                  }}
55	                >
56	                  {it.num ? (
57	                    <span className="punch-num" style={{ color: c, borderColor: `color-mix(in srgb, ${c} 45%, transparent)`, background: `color-mix(in srgb, ${c} 14%, transparent)` }}>{it.num}</span>
58	                  ) : (
59	                    <span className="kbd">{it.key.toUpperCase()}</span>
60	                  )}
61	                  <span className="material-symbols-outlined" style={{ fontSize: 18, color: c }}>{iconForAction(it.action)}</span>
62	                  <span style={{ fontSize: 12.5, fontWeight: 600, color: 'var(--text-secondary)', lineHeight: 1.1 }}>
63	                    {it.name}{previewTarget === 'Body' && <span style={{ color: 'var(--accent)' }}> · Body</span>}
64	                  </span>
65	                </button>
66	              );
67	            })}
68	          </div>
69	        </div>
70	      ))}
71	
72	      <div>
73	        <div className="label" style={{ fontSize: 9.5, marginBottom: 9 }}>Fight result</div>
74	        <button
75	          onClick={onFightEnd}
