              boxShadow: '0 0 16px color-mix(in srgb, var(--purple-600) 32%, transparent)', fontFamily: 'inherit',
            }}
          >
            <span className="material-symbols-outlined" style={{ fontSize: 18 }}>check</span>
            Record result
          </button>
        </div>
      </div>
    </div>
  );
}

