361	            className="tl-ruler"
362	            style={{ position: 'absolute', top: 0, left: 0, width: '100%', height: TL.ruler, cursor: 'ew-resize', borderBottom: '1px solid var(--border-glass)' }}
363	          >
364	            {ticks.map(t => (
