:root {
  font-family: 'Manrope', system-ui, sans-serif;
  line-height: 1.5;
  font-weight: 400;
  color-scheme: dark;
  color: #f5f5f4;
  background-color: #000;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;

  /* ── Brand design tokens (Fightlytics ember palette, Sept 2026) ──── */
  --bg-base: #000;
  --surface-glass: #0e0f12;
  --surface-glass-2: #15171b;
  --surface-inner: rgba(255,255,255,0.03);
  --header-bg: rgba(0,0,0,0.72);
  --text-primary: #f5f5f4;
  --text-secondary: #dcdad5;
  --text-tertiary: #9a9892;
  --text-muted: #9a9892;
  --text-disabled: #5c5a56;
  --accent: #ff4d1c;
  --accent-hover: #ff6a40;
  --accent-deep: #c1300a;
  --accent-on: #190500;
  --cyan-400: var(--accent);
  --cyan-600: var(--accent-deep);
  --cyan-on: var(--accent-on);
  --accent-2: var(--accent);
  /* Kept as true distinct hues rather than brand.css's literal collapse onto
     orange/ink — several components (StateDumbbell truth-vs-predicted dots,
     FighterColumn's Clinch vs Distance bars, SaveStatus, round markers) rely
     on these reading as their own colour, not a shade of the accent. See
     frontend-palette-collisions memory. */
  --purple-600: #7c3aed;
  --green-500: #0ca30c;
  --orange-400: #c98500;
  --orange-600: #e64a19;
  --red-500: #ef4444;
  --slate-400: #9a9892;
  --f-red: #ef4444;
  --f-red-dim: rgba(239,68,68,0.16);
  --f-blue: rgb(96,165,250);
  --f-blue-dim: rgba(96,165,250,0.16);
  --border-glass: rgba(255,255,255,0.10);
  --border-subtle: rgba(255,255,255,0.06);
  --border-cyan: rgba(255,77,28,0.35);
  --mono: 'JetBrains Mono', ui-monospace, Menlo, monospace;
  /* Annotate's STATE lane (STRIKING/CLINCH/GROUND) — validated with the
     dataviz skill's validate_palette.js against surface #0e0f12 and against
     --f-red/--f-blue (dark mode, all-pairs): all checks pass. Do not swap
     GROUND back to --f-red — that was the exact collision this fixes. */
  --state-striking: #199e70;
  --state-clinch: #c98500;
  --state-ground: #9085e9;
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  min-height: 100vh;
}

body {
  min-width: 320px;
}

#root {
  width: 100%;
}

h1, h2, h3, h4, h5, h6 {
  margin: 0;
}

a {
  font-weight: 500;
  color: var(--accent);
  text-decoration: none;
}
a:hover {
  color: var(--accent-hover);
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  outline: none;
  transition: opacity 0.15s, transform 0.15s, box-shadow 0.15s, background 0.15s;
}

button:active {
  transform: scale(0.97);
}

/* Corner-select cards: state change (border/bg/glow) must be instant, no scale/transform. */
.fighter-corner-btn,
.fighter-corner-btn:active {
  transition: none;
  transform: none;
}

button:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.material-symbols-outlined {
  font-variation-settings: 'FILL' 0, 'wght' 400, 'GRAD' 0, 'opsz' 24;
  user-select: none;
}

/* ── Display font ──────────────────────────────────── */

.font-display {
  font-family: 'Bebas Neue', sans-serif;
  letter-spacing: 0.02em;
}

/* ── Entry animations ──────────────────────────────── */

@keyframes fade-up {
  from { opacity: 0; transform: translateY(16px); }
  to   { opacity: 1; transform: translateY(0); }
}

.anim-fade-up {
  animation: fade-up 0.5s ease-out both;
}

.anim-delay-1 { animation-delay: 0.08s; }
.anim-delay-2 { animation-delay: 0.18s; }
.anim-delay-3 { animation-delay: 0.28s; }

/* ── Video overlay animations ──────────────────────── */

@keyframes video-feedback {
  0%   { opacity: 0.9;  transform: translate(-50%, -50%) scale(0.8); }
  30%  { opacity: 0.9;  transform: translate(-50%, -50%) scale(1.15); }
  100% { opacity: 0;    transform: translate(-50%, -50%) scale(1.45); }
}

@keyframes seek-pulse {
  0%, 100% { opacity: 0.9;  transform: translate(-50%, -50%) scale(1); }
  50%       { opacity: 0.9;  transform: translate(-50%, -50%) scale(1.18); }
}

@keyframes seek-fade {
  from { opacity: 0.9;  transform: translate(-50%, -50%) scale(1); }
  to   { opacity: 0;    transform: translate(-50%, -50%) scale(1.35); }
}

/* ── Hover states ───────────────────────────────────── */

.btn-glass {
  background: transparent;
  border: 1px solid rgba(255,255,255,0.28);
  border-radius: 999px;
  color: var(--text-primary);
  display: flex;
  align-items: center;
  justify-content: center;
}

.btn-glass:hover {
  background: rgba(255,255,255,0.06);
  color: var(--text-primary);
}

.btn-primary:hover {
  background: var(--accent-hover);
}

.btn-upload,
.btn-primary {
  background: var(--accent);
  color: var(--accent-on);
  border: none;
  border-radius: 999px;
  box-shadow: none;
}

.btn-upload:hover {
  background: var(--accent-hover);
}

.logo {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  font-family: 'Bebas Neue', sans-serif;
  font-size: 26px;
  line-height: 1;
  letter-spacing: 0.055em;
  text-transform: uppercase;
  color: var(--text-primary);
  white-space: nowrap;
  text-decoration: none;
}
.logo:hover {
  color: var(--text-primary);
}

.nav-link {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-muted);
  padding: 8px 16px;
  border-radius: 999px;
  border: 1px solid transparent;
  text-decoration: none;
  cursor: pointer;
  transition: color 0.15s, background 0.15s;
}

.nav-link:hover {
  color: var(--text-primary) !important;
  background: transparent !important;
}

.nav-link.active {
  color: var(--text-primary) !important;
  background: var(--surface-glass-2) !important;
  border-color: var(--border-glass) !important;
}

.event-item:hover {
  background: rgba(255,255,255,0.03) !important;
}

/* ── Glass surfaces & helper classes ───────────────── */

.glass {
  background: var(--surface-glass);
  border: 1px solid var(--border-glass);
  border-radius: 16px;
}

.inner-tile {
  background: var(--surface-inner);
  border: 1px solid var(--border-subtle);
  border-radius: 12px;
}

.divider {
  height: 1px;
  background: var(--border-glass);
  border: none;
  margin: 0;
}

.label {
  font-size: 10.5px;
  font-weight: 600;
  text-transform: none;
  letter-spacing: 0;
  color: var(--text-muted);
}

.pill {
  font-size: 11.5px;
  font-weight: 700;
  padding: 6px 13px;
  border-radius: 999px;
  border: 1px solid transparent;
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
}

.pill.active {
  background: var(--surface-glass-2);
  color: var(--text-primary);
  border-color: var(--border-glass);
  box-shadow: none;
}

/* ── Feed animations ────────────────────────────────── */

@keyframes feed-in {
  from { transform: translateY(9px); opacity: 0; }
  to   { transform: translateY(0);   opacity: 1; }
}

@keyframes pulse-ring {
  0%   { box-shadow: 0 0 0 0 color-mix(in srgb, var(--accent) 45%, transparent); }
  70%  { box-shadow: 0 0 0 8px transparent; }
  100% { box-shadow: 0 0 0 0 transparent; }
}

@keyframes scope-pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50%       { opacity: 0.4; transform: scale(0.7); }
}

@keyframes spin {
  from { transform: rotate(0deg); }
  to   { transform: rotate(360deg); }
}

/* ── Scrollbar ──────────────────────────────────────── */

::-webkit-scrollbar { width: 5px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.1); border-radius: 10px; }
::-webkit-scrollbar-thumb:hover { background: rgba(255,255,255,0.2); }

/* ── Annotate screen ────────────────────────────────── */

.kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 22px;
  height: 22px;
  padding: 0 6px;
  border-radius: 6px;
  background: rgba(255,255,255,0.07);
  border: 1px solid var(--border-glass);
  border-bottom-width: 2px;
  font-size: 11px;
  font-weight: 800;
  color: var(--text-secondary);
  font-family: 'Manrope', sans-serif;
  letter-spacing: 0.02em;
  flex-shrink: 0;
}

.punch-num {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  border-radius: 6px;
  border: 1px solid;
  font-size: 12px;
  font-weight: 800;
  font-family: 'Manrope', sans-serif;
  flex-shrink: 0;
}

.tl-scroll::-webkit-scrollbar { height: 10px; }
.tl-scroll::-webkit-scrollbar-track { background: rgba(255,255,255,0.03); }
.tl-scroll::-webkit-scrollbar-thumb {
  background: rgba(255,255,255,0.16);
  border-radius: 6px;
  border: 2px solid transparent;
  background-clip: padding-box;
}
.tl-scroll::-webkit-scrollbar-thumb:hover {
  background: rgba(255,255,255,0.28);
  background-clip: padding-box;
}

.tl-clip { padding: 0; transition: transform .1s; }
.tl-clip:hover { transform: translateY(-1px) scale(1.08); }
.tl-ruler:hover { background: rgba(255,255,255,0.025); }

.icon-btn {
  width: 40px;
  height: 40px;
  border-radius: 999px;
  display: grid;
  place-items: center;
  background: transparent;
  border: 1px solid var(--border-glass);
  color: var(--text-muted);
  cursor: pointer;
}

.icon-btn:hover {
  color: var(--text-primary);
  background: var(--surface-glass-2);
}

