1	import { useState, useEffect, useRef } from 'react';
2	import { createPortal } from 'react-dom';
3	import type { Fighter } from '../types/Fighter';
4	import type { Fight, FightPurpose } from '../types/Fight';
5	import { PURPOSE_LABELS } from '../types/Fight';
6	import { uploadFight } from '../services/api';
7	import CornerSelect from './CornerSelect';
8	import ModeCard from './ModeCard';
9	
10	/**
11	 * The two purposes a self-annotated video can have. They must stay disjoint —
12	 * a fight that trains the model can't also be the yardstick it's measured by.
13	 */
14	const PURPOSE_CHOICES: { value: 'training_data' | 'reference'; desc: string }[] = [
15	  {
16	    value: 'training_data',
17	    desc: 'Labels feed model training. Never scored against the pipeline.',
18	  },
19	  {
20	    value: 'reference',
21	    desc: 'Held out of training. Used to measure pipeline accuracy.',
22	  },
23	];
24	
25	interface UploadDialogProps {
26	  open: boolean;
27	  onClose: () => void;
28	  onSuccess: (fight: Fight, purpose: FightPurpose) => void;
29	}
30	
31	export default function UploadDialog({ open, onClose, onSuccess }: UploadDialogProps) {
32	  const [mode, setMode] = useState<'manual' | 'ai'>('ai');
33	  // Deliberately starts null: the training/eval split must never be decided
34	  // by inattention, so Upload stays disabled until one is picked.
35	  const [manualPurpose, setManualPurpose] = useState<'training_data' | 'reference' | null>(null);
36	  const [file, setFile] = useState<File | null>(null);
37	  const [drag, setDrag] = useState(false);
38	  const [redF, setRedF] = useState<Fighter | null>(null);
39	  const [blueF, setBlueF] = useState<Fighter | null>(null);
40	  const [uploading, setUploading] = useState(false);
41	  const [error, setError] = useState<string | null>(null);
42	  const inputRef = useRef<HTMLInputElement>(null);
43	
44	  useEffect(() => {
45	    if (open) {
46	      setMode('ai');
47	      setManualPurpose(null);
48	      setFile(null);
49	      setDrag(false);
50	      setRedF(null);
51	      setBlueF(null);
52	      setUploading(false);
53	      setError(null);
54	    }
55	  }, [open]);
56	
57	  useEffect(() => {
58	    if (!open || uploading) return;
59	    const onKey = (e: KeyboardEvent) => { if (e.key === 'Escape') onClose(); };
60	    window.addEventListener('keydown', onKey);
61	    return () => window.removeEventListener('keydown', onKey);
62	  }, [open, uploading, onClose]);
63	
64	  if (!open) return null;
65	
66	  const takeFile = (f: File | null) => {
67	    if (f) { setFile(f); setError(null); }
68	  };
69	
70	  const sizeMB = file ? (file.size / 1048576).toFixed(1) + ' MB' : '';
71	  const purpose: FightPurpose | null = mode === 'ai' ? 'ai_labeled' : manualPurpose;
72	  const ready = !!file && !!redF && !!blueF && !!purpose;
73	
74	  const handleSubmit = async () => {
75	    if (!ready || uploading) return;
76	    setUploading(true);
77	    setError(null);
78	    try {
79	      const fight = await uploadFight(file, redF.id, blueF.id, purpose);
80	      onSuccess(fight, purpose);
81	    } catch (err) {
82	      setError(err instanceof Error ? err.message : 'Upload failed');
83	      setUploading(false);
84	    }
85	  };
86	
87	  const helperText = uploading
88	    ? 'Uploading…'
89	    : !file
90	      ? 'Add a video to continue'
91	      : !redF || !blueF
92	        ? 'Assign both corner fighters'
93	        : mode === 'manual' && !manualPurpose
94	          ? 'Choose what this footage is for'
95	          : mode === 'manual'
96	            ? 'Fighters will be detected, then it\'s ready for you to label'
97	            : 'AI will process after upload';
98	
99	  return createPortal(
100	    <div
101	      onClick={uploading ? undefined : onClose}
102	      style={{
103	        position: 'fixed', inset: 0, zIndex: 1000, display: 'grid', placeItems: 'center', padding: 24,
104	        background: 'rgba(3,5,7,0.66)', backdropFilter: 'blur(10px)', WebkitBackdropFilter: 'blur(10px)',
105	        animation: 'fade-up .2s ease-out',
106	      }}
107	    >
108	      <div
109	        onClick={e => e.stopPropagation()}
110	        style={{
111	          width: 'min(640px, 100%)', maxHeight: '90vh', overflowY: 'auto', borderRadius: 18, padding: 0,
112	          background: 'rgba(11,15,20,0.97)',
113	          border: '1px solid rgba(255,255,255,0.07)',
114	          backdropFilter: 'blur(20px) saturate(160%)', WebkitBackdropFilter: 'blur(20px) saturate(160%)',
115	          boxShadow: '0 40px 120px -30px rgba(0,0,0,0.85)',
116	          animation: 'fade-up .25s ease-out',
117	        }}
118	      >
119	        {/* Header */}
120	        <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: 16, padding: '24px 26px 18px' }}>
121	          <div>
122	            <div className="font-display" style={{ fontSize: 30, letterSpacing: '0.03em', color: '#f1f5f9', lineHeight: 1 }}>UPLOAD VIDEO</div>
123	            <div style={{ fontSize: 13, color: '#64748b', fontWeight: 600, marginTop: 6 }}>Add a fight and choose how events get broken down.</div>
124	          </div>
125	          {!uploading && (
126	            <button
127	              onClick={onClose}
128	              style={{
129	                width: 34, height: 34, flexShrink: 0, borderRadius: 10, display: 'grid', placeItems: 'center',
130	                background: 'rgba(255,255,255,0.04)', border: '1px solid rgba(255,255,255,0.07)',
131	                color: '#94a3b8', cursor: 'pointer',
132	              }}
133	            >
134	              <span className="material-symbols-outlined" style={{ fontSize: 20 }}>close</span>
135	            </button>
136	          )}
137	        </div>
138	
139	        {/* Dropzone */}
140	        <div style={{ padding: '0 26px' }}>
141	          <input
142	            ref={inputRef}
143	            type="file"
144	            accept="video/*"
145	            style={{ display: 'none' }}
146	            onChange={e => takeFile(e.target.files?.[0] ?? null)}
147	          />
148	          <div
149	            onClick={() => !uploading && inputRef.current?.click()}
150	            onDragOver={e => { e.preventDefault(); if (!uploading) setDrag(true); }}
151	            onDragLeave={() => setDrag(false)}
152	            onDrop={e => { e.preventDefault(); setDrag(false); if (!uploading) takeFile(e.dataTransfer.files?.[0] ?? null); }}
153	            style={{
154	              cursor: uploading ? 'default' : 'pointer', borderRadius: 14,
155	              padding: file ? '16px 18px' : '26px 18px',
156	              border: `1.5px dashed ${drag ? '#00daf3' : 'rgba(255,255,255,0.07)'}`,
157	              background: drag ? 'rgba(0,218,243,0.08)' : 'rgba(0,0,0,0.30)',
158	              display: 'flex', alignItems: 'center', gap: 16,
159	              transition: 'border-color .14s, background .14s',
160	              opacity: uploading ? 0.5 : 1,
161	            }}
162	          >
