1	import { useState, useEffect, useRef, useCallback } from 'react';
2	import type { Fighter } from '../types/Fighter';
3	import { fetchFighters, createFighter } from '../services/api';
4	
5	interface CornerSelectProps {
6	  corner: string;
7	  dotColor: string;
8	  value: Fighter | null;
9	  exclude: number | null;
10	  onChange: (fighter: Fighter | null) => void;
11	  disabled?: boolean;
12	}
13	
14	const fighterFull = (f: Fighter) => `${f.first_name} ${f.last_name}`;
15	const fighterInitials = (f: Fighter) =>
16	  `${f.first_name[0] ?? ''}${f.last_name[0] ?? ''}`.toUpperCase();
17	
18	const fieldStyle: React.CSSProperties = {
19	  width: '100%', boxSizing: 'border-box', background: 'rgba(0,0,0,0.35)',
20	  border: '1px solid rgba(255,255,255,0.07)', borderRadius: 8,
21	  padding: '9px 11px', color: '#f1f5f9', fontSize: 13, fontWeight: 600, outline: 'none',
22	  fontFamily: 'inherit',
23	};
24	
25	export default function CornerSelect({ corner, dotColor, value, exclude, onChange, disabled }: CornerSelectProps) {
26	  const [open, setOpen] = useState(false);
27	  const [q, setQ] = useState('');
28	  const [creating, setCreating] = useState(false);
29	  const [nf, setNf] = useState({ first: '', last: '', nick: '' });
30	  const [fighters, setFighters] = useState<Fighter[]>([]);
31	  const [loadingFighters, setLoadingFighters] = useState(false);
32	  const wrapRef = useRef<HTMLDivElement>(null);
33	  const searchRef = useRef<HTMLInputElement>(null);
34	  const debounceRef = useRef<ReturnType<typeof setTimeout>>(undefined);
35	
36	  useEffect(() => {
37	    if (!open) return;
38	    const onDoc = (e: MouseEvent) => {
39	      if (wrapRef.current && !wrapRef.current.contains(e.target as Node)) {
40	        setOpen(false);
41	        setCreating(false);
42	      }
43	    };
44	    window.addEventListener('mousedown', onDoc);
45	    return () => window.removeEventListener('mousedown', onDoc);
46	  }, [open]);
47	
48	  useEffect(() => {
49	    if (open && !creating && searchRef.current) searchRef.current.focus();
50	  }, [open, creating]);
51	
52	  const searchFighters = useCallback((query: string) => {
53	    setLoadingFighters(true);
54	    fetchFighters(query || undefined)
55	      .then(setFighters)
56	      .catch(() => {})
57	      .finally(() => setLoadingFighters(false));
58	  }, []);
59	
60	  useEffect(() => {
61	    if (!open) return;
62	    searchFighters('');
63	  }, [open, searchFighters]);
64	
65	  const onSearchChange = (val: string) => {
66	    setQ(val);
67	    clearTimeout(debounceRef.current);
68	    debounceRef.current = setTimeout(() => searchFighters(val.trim()), 250);
69	  };
70	
71	  const filtered = fighters.filter(f => f.id !== exclude);
72	
73	  const pick = (f: Fighter) => {
74	    onChange(f);
75	    setOpen(false);
76	    setCreating(false);
77	    setQ('');
78	  };
79	
80	  const beginCreate = () => {
81	    const parts = q.trim().split(/\s+/);
82	    setNf({ first: parts[0] || '', last: parts.slice(1).join(' ') || '', nick: '' });
83	    setCreating(true);
84	  };
85	
86	  const commitCreate = async () => {
87	    const first = nf.first.trim();
88	    const last = nf.last.trim();
89	    if (!first || !last) return;
90	    try {
91	      const fighter = await createFighter({
92	        first_name: first,
93	        last_name: last,
94	        nickname: nf.nick.trim() || undefined,
95	      });
96	      pick(fighter);
97	      setNf({ first: '', last: '', nick: '' });
98	    } catch {
99	      // stay in create view on error
100	    }
101	  };
102	
103	  return (
104	    <div ref={wrapRef} style={{ position: 'relative' }}>
105	      <div style={{
106	        display: 'flex', alignItems: 'center', gap: 7, marginBottom: 8,
107	        fontSize: 10.5, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.12em', color: 'rgba(255,255,255,0.28)',
108	      }}>
109	        <span style={{ width: 9, height: 9, borderRadius: '50%', background: dotColor, boxShadow: `0 0 8px ${dotColor}` }} />
110	        {corner}
111	      </div>
112	
113	      <button
114	        type="button"
115	        onClick={() => !disabled && setOpen(o => !o)}
116	        style={{
117	          width: '100%', textAlign: 'left', cursor: disabled ? 'not-allowed' : 'pointer',
118	          display: 'flex', alignItems: 'center', gap: 11, padding: '11px 12px',
119	          borderRadius: 11, background: 'rgba(0,0,0,0.30)',
120	          border: `1.5px solid ${open ? 'rgba(0,218,243,0.6)' : 'rgba(255,255,255,0.07)'}`,
121	          boxShadow: open ? '0 0 0 3px rgba(0,218,243,0.15)' : 'none',
122	          transition: 'border-color .14s',
123	          opacity: disabled ? 0.5 : 1,
124	          fontFamily: 'inherit',
125	        }}
126	      >
127	        <span style={{
128	          width: 34, height: 34, flexShrink: 0, borderRadius: 9, display: 'grid', placeItems: 'center',
129	          fontSize: 12, fontWeight: 800,
130	          background: value ? `color-mix(in srgb, ${dotColor} 22%, transparent)` : 'rgba(255,255,255,0.05)',
131	          color: value ? dotColor : '#475569',
132	          border: `1px solid ${value ? `color-mix(in srgb, ${dotColor} 40%, transparent)` : 'rgba(255,255,255,0.07)'}`,
