11	
12	// Same grouping ClassGrid/the Annotate palette use, computed once — a
13	// <select> with <optgroup>s so "retype this strike" reads like the palette
14	// it was originally logged from, not a flat alphabetical dump.
15	const TYPE_GROUPS: { name: string; items: TrainingClass[] }[] = (() => {
16	  const groups: { name: string; items: TrainingClass[] }[] = [];
17	  TRAINING_CLASSES.forEach((c) => {
18	    let g = groups.find((x) => x.name === c.group);
19	    if (!g) { g = { name: c.group, items: [] }; groups.push(g); }
20	    g.items.push(c);
21	  });
22	  return groups;
23	})();
24	
25	/** EventReview's "Type" dropdown — retypes a mislabelled strike in place.
26	 * Saves on change (no separate confirm step); disables itself and shows an
27	 * inline error if the write fails, same pattern as the rest of Annotate's
28	 * autosave. */
29	function TypeSelect({ action, onChange }: { action: string; onChange: (newAction: string) => Promise<void> }) {
30	  const [saving, setSaving] = useState(false);
31	  const [error, setError] = useState<string | null>(null);
32	
33	  const handleChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
34	    const next = e.target.value;
35	    if (next === action) return;
36	    setSaving(true);
37	    setError(null);
38	    onChange(next)
39	      .catch((err) => setError(err instanceof Error ? err.message : 'Failed to save'))
40	      .finally(() => setSaving(false));
41	  };
42	
43	  return (
44	    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: 3 }}>
45	      <select
46	        value={action}
47	        onChange={handleChange}
48	        disabled={saving}
49	        style={{
