          <p style={{ margin: '5px 0 0', fontSize: 12.5, fontWeight: 600, color: 'var(--text-muted)' }}>
            {s.total} labelled events · exports as <code style={{ fontFamily: 'var(--mono)', fontSize: 11.5, color: 'var(--accent-hover)' }}>{cls.action}</code>
          </p>
        </div>
        <button
