            marginLeft: 'auto', background: 'linear-gradient(135deg, var(--accent), var(--accent-deep))', color: 'var(--accent-on)',
            fontWeight: 700, fontSize: 13, border: 'none', borderRadius: 999, padding: '9px 16px',
