1	/**
2	 * One `python -m eval.cli score-pair` run: a `purpose='reference'` fight's
3	 * hand labels scored against a `purpose='ai_labeled'` fight's pipeline
4	 * predictions — two different fight ids, per the real accuracy workflow (see
5	 * frontend/CLAUDE.md "Fight purpose" and backend/CLAUDE.md).
6	 *
7	 * `f1`/`precision`/`recall`/`tp`/`fp`/`fn`/`offset_bias_frames`/
8	 * `offset_jitter_frames` are computed server-side at read time from the
9	 * stored report's raw tp/fp/fn/matched_offsets — mirrors ai/eval/score.py's
10	 * PRF properties, since dataclasses.asdict() doesn't serialise properties.
11	 */
12	export interface EvalRunSummary {
13	  id: number;
14	  reference_fight_id: number;
15	  scored_fight_id: number;
16	  /** 1-based rank of `scored_fight_id` among this fixture's scored fights, in
17	   * upload order — a fight's pipeline never re-runs, so each new pipeline
18	   * version is a new ai_labeled upload. Stamped server-side. */
19	  pipeline_version: number;
20	  /** The scorer's HEAD when this run was scored — NOT the code that produced
21	   * the scored fight's predictions. */
22	  git_sha: string;
23	  constants_sha256: string;
24	  tolerance_secs: number;
25	  tolerance_frames: number;
26	  scored_minutes: number;
27	  generated_at: string;
28	  triggered_by: string | null;
29	  f1: number | null;
30	  precision: number | null;
31	  recall: number | null;
32	  tp: number | null;
33	  fp: number | null;
34	  fn: number | null;
35	  offset_bias_frames: number | null;
36	  offset_jitter_frames: number | null;
37	}
38	
39	/** e.g. `v1 · #62` — the pipeline version and the ai_labeled fight it is. */
40	export const versionLabel = (run: EvalRunSummary) => `v${run.pipeline_version} · #${run.scored_fight_id}`;
41	
42	/** One run per pipeline version, oldest version first — each version's latest
43	 * scoring (`runs` arrive oldest first, so later runs overwrite earlier ones).
44	 * Re-scoring the same fight, e.g. after a scorer fix, replaces its point
45	 * rather than posing as a new version. */
46	export const latestPerVersion = (runs: EvalRunSummary[]): EvalRunSummary[] =>
47	  [...new Map(runs.map((r) => [r.pipeline_version, r])).values()]
48	    .sort((a, b) => a.pipeline_version - b.pipeline_version);
49	
50	/** A ground-truth (label) strike — see ai/eval/schema.py's `Strike`. */
51	export interface LabelStrike {
52	  frame: number;
53	  fighter: 'red' | 'blue';
54	  family: string;
55	  target: string;
56	  landed: boolean | null;
57	}
58	
59	/** A pipeline-predicted strike — `Strike` plus the raw pipeline action
60	 * string (e.g. `jab_head`) — see ai/eval/predictions.py's `PredictedStrike`. */
61	export interface PredictedStrikeItem extends LabelStrike {
62	  action: string;
63	}
64	
65	/** One round's match — see ai/eval/score.py's `RoundScore.matched`:
66	 * [round_num, iou, start_offset_secs, end_offset_secs, seeded]. `seeded`
67	 * true means the label round is unverified (still byte-identical to what it
68	 * was auto-seeded from) — its IoU would be circular, so show that instead. */
69	export type MatchedRound = [number, number, number, number, boolean];
70	
71	/** The full ai/eval/score.py `Report`, as persisted by report_io.save_report
72	 * / save_eval_run_db — same shape whether it came from the DB or a checked-in
73	 * ai/eval/baselines/*.json file. */
74	export interface EvalReport {
75	  video: string;
76	  fps: number;
77	  scored_minutes: number;
