export type Status = 'good' | 'warning' | 'critical' | 'unverified' | 'none' | 'circular';

/**
 * Icon + text always paired, never colour alone — good/critical collapse for
 * red-green colourblindness, and critical's red is close to the red corner.
 * `good`/`warning` use their own hex rather than the app's `--green-500`/
 * `--red-500` tokens: those are already claimed by other meanings
 * (training_data purpose, round spans) — see memory "frontend-palette-collisions".
 */
const STATUS: Record<Status, { color: string; icon: string }> = {
  good: { color: '#0ca30c', icon: 'check_circle' },
  warning: { color: '#fab219', icon: 'warning' },
  critical: { color: 'var(--red-500)', icon: 'error' },
  unverified: { color: 'var(--text-muted)', icon: 'help' },
  none: { color: 'var(--text-muted)', icon: 'remove' },
  circular: { color: '#b39dfb', icon: 'sync_problem' },
};

interface StatusBadgeProps {
  status: Status;
  children: React.ReactNode;
  size?: 'sm' | 'md';
  title?: string;
}

export default function StatusBadge({ status, children, size = 'md', title }: StatusBadgeProps) {
  const s = STATUS[status];
  const sm = size === 'sm';
  return (
    <span
      title={title}
      style={{
        display: 'inline-flex',
        alignItems: 'center',
        gap: sm ? 4 : 5,
        flexShrink: 0,
        whiteSpace: 'nowrap',
        padding: sm ? '2px 6px 2px 5px' : '3px 8px 3px 6px',
        borderRadius: 6,
        background: `color-mix(in srgb, ${s.color} 13%, transparent)`,
        border: `1px solid color-mix(in srgb, ${s.color} 26%, transparent)`,
        color: s.color,
        fontSize: sm ? 10 : 11,
        fontWeight: 700,
        letterSpacing: '0.01em',
      }}
    >
      <span className="material-symbols-outlined" style={{ fontSize: sm ? 11 : 13 }}>{s.icon}</span>
      {children}
    </span>
  );
}

const TERMS: { term: string; def: string }[] = [
  { term: 'TP', def: 'true positive — a predicted strike matched to a real labelled one' },
  { term: 'FP', def: 'false positive — predicted, but no matching label (a false alarm)' },
  { term: 'FN', def: 'false negative — labelled, but never predicted (a miss)' },
  { term: 'P', def: 'precision — of everything predicted, the % that was real: TP ÷ (TP + FP)' },
  { term: 'R', def: 'recall — of everything real, the % that got predicted: TP ÷ (TP + FN)' },
  { term: 'F1', def: 'one number for both — the harmonic mean of precision and recall' },
  { term: 'IoU', def: 'intersection over union — how much a predicted round overlaps the labelled one' },
];

/**
 * Acronym key for TP/FP/FN/P/R/F1 (FixtureTable, HeadlineF1, VersionTrendChart)
 * and IoU (RoundsCheck). Spelled out once, always visible, rather than as
 * hover-only tooltips — every other honesty affordance on this page
 * (ProvenanceLine, the "Seeded — not verified" badges) stays on screen
 * instead of hiding behind an interaction, so the glossary follows the same
 * rule.
 */
export default function Glossary() {
  return (
    <div style={{
      display: 'flex', flexWrap: 'wrap', rowGap: 6, columnGap: 16,
      fontSize: 11, fontWeight: 600, color: 'var(--text-muted)',
      padding: '10px 12px', marginTop: 12, borderRadius: 8,
      background: 'rgba(255,255,255,0.02)', border: '1px solid var(--border-subtle)',
    }}>
      {TERMS.map(({ term, def }) => (
        <span key={term}>
          <code style={{ color: '#9fe8f4', fontWeight: 700 }}>{term}</code> {def}
        </span>
      ))}
    </div>
  );
}

