    else if (sort === 'Round min') sorted.sort((a, b) => b.row.minutes - a.row.minutes);
    else if (sort === 'Warnings') sorted.sort((a, b) => b.d.warnings.length - a.d.warnings.length);
    else sorted.sort((a, b) => a.row.fight.id - b.row.fight.id);
    return sorted;
