interface AccGaugeProps {
  pct: number;
  color: string;
  label: string;
}

export default function AccGauge({ pct, color, label }: AccGaugeProps) {
  const r = 26, c = 2 * Math.PI * r;
  return (
    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 6 }}>
      <div style={{ position: 'relative', width: 64, height: 64 }}>
        <svg width="64" height="64" style={{ transform: 'rotate(-90deg)' }}>
          <circle cx="32" cy="32" r={r} fill="none" stroke="rgba(255,255,255,0.06)" strokeWidth="6" />
          <circle cx="32" cy="32" r={r} fill="none" stroke={color} strokeWidth="6" strokeLinecap="round"
            strokeDasharray={`${pct / 100 * c} ${c}`} />
        </svg>
        <div style={{ position: 'absolute', inset: 0, display: 'grid', placeItems: 'center' }}>
          <span style={{ fontSize: 15, fontWeight: 800, color: 'var(--text-primary)' }}>{pct}%</span>
        </div>
      </div>
      <span style={{ fontSize: 10.5, color: 'var(--text-muted)', fontWeight: 700, letterSpacing: '0.06em', textTransform: 'uppercase' as const }}>{label}</span>
    </div>
  );
}

export interface EdgeTape {
  label: string;
  r: string | number;
  b: string | number;
  lowerWins?: boolean;
}

function tapeNum(v: string | number): number {
  if (typeof v === 'number') return v;
  const ft = /(\d+)'(\d+)/.exec(v);
  if (ft) return (+ft[1]) * 12 + (+ft[2]);
  const inch = /(\d+)"/.exec(v);
  if (inch) return +inch[1];
  return parseFloat(v) || 0;
}

function tapeDelta(t: EdgeTape) {
  const rn = tapeNum(t.r), bn = tapeNum(t.b);
  const rWin = t.lowerWins ? rn < bn : rn > bn;
  const bWin = t.lowerWins ? bn < rn : bn > rn;
  const diff = Math.abs(rn - bn);
  const unit = t.label === 'Age' ? (diff === 1 ? ' yr' : ' yrs') : '"';
  const winnerColor = rWin ? 'var(--f-red)' : (bWin ? 'var(--f-blue)' : 'var(--text-disabled)');
  return { rWin, bWin, diff, unit, winnerColor };
}

export function EdgeRow({ t }: { t: EdgeTape }) {
  const { rWin, bWin, diff, unit, winnerColor } = tapeDelta(t);
  const lean = Math.min(diff / 8, 1) * 50;
  return (
    <div style={{ marginBottom: 20 }}>
      <div style={{ display: 'grid', gridTemplateColumns: '58px 1fr 58px', alignItems: 'center', gap: 16 }}>
        <span className="font-display" style={{ fontSize: 23, textAlign: 'right', color: rWin ? 'var(--f-red)' : 'var(--text-tertiary)' }}>{t.r}</span>
        <div>
          <div style={{ textAlign: 'center', fontSize: 9.5, fontWeight: 700, letterSpacing: '0.14em', textTransform: 'uppercase' as const, color: 'var(--text-muted)', marginBottom: 7 }}>
            {t.label}
          </div>
          <div style={{ position: 'relative', height: 12 }}>
            <div style={{ position: 'absolute', inset: 0, borderRadius: 6, background: 'var(--surface-inner)', border: '1px solid var(--border-subtle)' }} />
            <div style={{ position: 'absolute', top: 0, bottom: 0, left: '50%', width: 1, background: 'var(--border-glass)' }} />
            {diff > 0 && (
              <div style={{ position: 'absolute', top: 1, bottom: 1, left: rWin ? `${50 - lean}%` : '50%', width: `${lean}%`, borderRadius: 6, background: winnerColor, boxShadow: `0 0 10px ${winnerColor}` }} />
            )}
          </div>
          <div style={{ textAlign: 'center', marginTop: 7, fontSize: 10, fontWeight: 800, letterSpacing: '0.04em', color: winnerColor }}>
            {diff > 0 ? `+${diff}${unit}` : 'EVEN'}
          </div>
        </div>
        <span className="font-display" style={{ fontSize: 23, textAlign: 'left', color: bWin ? 'var(--f-blue)' : 'var(--text-tertiary)' }}>{t.b}</span>
      </div>
    </div>
  );
}

import { useWindowWidth } from '../../hooks/useWindowWidth';
import type { FighterProfile } from '../../mocks/fightMock';
import { EdgeRow } from './EdgeMeter';
import type { EdgeTape } from './EdgeMeter';
import FormList from './RecentForm';

interface MatchupCardProps {
  fighters: { red: FighterProfile; blue: FighterProfile };
}

export default function MatchupCard({ fighters }: MatchupCardProps) {
  const width = useWindowWidth();
  const narrow = width < 1100;
  const r = fighters.red, b = fighters.blue;

  const EDGE_TAPE: EdgeTape[] = [
    { label: 'Height', r: r.height, b: b.height },
    { label: 'Reach',  r: r.reach,  b: b.reach  },
    { label: 'Age',    r: r.age,    b: b.age,    lowerWins: true },
  ];

  return (
    <div className="glass" style={{ marginTop: 16, padding: '22px 24px' }}>
      {/* Tale of the tape header */}
      <div style={{ display: 'grid', gridTemplateColumns: narrow ? '1fr' : '1fr auto 1fr', gap: 0, alignItems: 'center' }}>
        <div style={{ textAlign: narrow ? 'center' : 'left' }}>
          <div className="font-display" style={{ fontSize: 46, lineHeight: 0.9, color: r.color }}>{r.name}</div>
          <div style={{ fontSize: 13, color: 'var(--text-muted)', fontWeight: 600, marginTop: 4 }}>
            {r.first} · {r.country} · {r.record}
          </div>
        </div>
        {!narrow && (
          <div style={{ padding: '0 34px', textAlign: 'center' }}>
            <div className="font-display" style={{ fontSize: 30, color: 'var(--text-disabled)' }}>VS</div>
          </div>
        )}
        <div style={{ textAlign: narrow ? 'center' : 'right', marginTop: narrow ? 12 : 0 }}>
          <div className="font-display" style={{ fontSize: 46, lineHeight: 0.9, color: b.color }}>{b.name}</div>
          <div style={{ fontSize: 13, color: 'var(--text-muted)', fontWeight: 600, marginTop: 4 }}>
            {b.first} · {b.country} · {b.record}
          </div>
        </div>
      </div>

      {/* Edge meters */}
      <div style={{ maxWidth: 600, margin: '24px auto 0' }}>
        {EDGE_TAPE.map((t, i) => <EdgeRow key={i} t={t} />)}
      </div>

      {/* Recent form divider */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 12, margin: '24px auto 16px', maxWidth: 560 }}>
        <hr className="divider" style={{ flex: 1 }} />
        <span style={{ fontSize: 10, fontWeight: 700, letterSpacing: '0.14em', textTransform: 'uppercase', color: 'var(--text-disabled)', whiteSpace: 'nowrap' }}>
          Recent Form · Last 5
        </span>
        <hr className="divider" style={{ flex: 1 }} />
      </div>

