16	  const missing = fight.reported_frames - fight.decoded_frames;
17	  const pct = fight.reported_frames > 0 ? Math.round((missing / fight.reported_frames) * 100) : 0;
18	  return `Container reports ${fight.reported_frames} frames, only ${fight.decoded_frames} decode `
